import { Component, DestroyRef, computed, inject, input, signal } from '@angular/core';
import { NzTooltipDirective } from 'ng-zorro-antd/tooltip';

/** Đổi mốc thời gian → chuỗi tương đối theo locale ("3 giờ trước", "hôm qua") bằng
 *  Intl.RelativeTimeFormat — không cần thư viện. Dùng chung cho hrm-timestamp / date-cell. */
export function hrmRelativeTime(value: Date | string | number, locale = 'vi-VN', now: Date = new Date()): string {
  const d = value instanceof Date ? value : new Date(value);
  if (isNaN(d.getTime())) return String(value);
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: 'auto' });
  const diffSec = Math.round((d.getTime() - now.getTime()) / 1000);
  const abs = Math.abs(diffSec);
  if (abs < 60) return rtf.format(Math.trunc(diffSec), 'second');
  if (abs < 3600) return rtf.format(Math.trunc(diffSec / 60), 'minute');
  if (abs < 86400) return rtf.format(Math.trunc(diffSec / 3600), 'hour');
  if (abs < 2592000) return rtf.format(Math.trunc(diffSec / 86400), 'day');
  if (abs < 31536000) return rtf.format(Math.trunc(diffSec / 2592000), 'month');
  return rtf.format(Math.trunc(diffSec / 31536000), 'year');
}

/** hrm-timestamp — hiện thời gian TƯƠNG ĐỐI ("3 giờ trước") tự cập nhật mỗi phút;
 *  mode='both' kèm tooltip giờ tuyệt đối đầy đủ. mode='absolute' chỉ hiện giờ đầy đủ.
 *  Locale theo input — đổi ngôn ngữ app thì caller truyền locale tương ứng. */
@Component({
  selector: 'hrm-timestamp',
  imports: [NzTooltipDirective],
  template: `
    @if (mode() === 'absolute') {
      <span class="ts">{{ absolute() }}</span>
    } @else if (mode() === 'relative') {
      <span class="ts">{{ relative() }}</span>
    } @else {
      <span class="ts ts--tip" nz-tooltip [nzTooltipTitle]="absolute()">{{ relative() }}</span>
    }
  `,
  host: { class: 'hrm-timestamp' },
  styles: [`
:host { display: inline-flex; }
.ts { font-size: var(--fs-13); color: var(--text-sub); white-space: nowrap; }
.ts--tip { cursor: default; text-decoration: underline dotted var(--border-input); text-underline-offset: 3px; }
  `],
})
export class HrmTimestamp {
  readonly value = input<Date | string | number | null>(null);
  readonly locale = input('vi-VN');
  readonly mode = input<'relative' | 'absolute' | 'both'>('both');

  /** Tick mỗi 60s để chuỗi tương đối tự tươi. */
  private readonly tick = signal(0);

  constructor() {
    const id = setInterval(() => this.tick.update((n) => n + 1), 60_000);
    inject(DestroyRef).onDestroy(() => clearInterval(id));
  }

  protected readonly relative = computed(() => {
    this.tick();
    const v = this.value();
    return v == null || v === '' ? '' : hrmRelativeTime(v, this.locale());
  });

  protected readonly absolute = computed(() => {
    const v = this.value();
    if (v == null || v === '') return '';
    const d = v instanceof Date ? v : new Date(v);
    if (isNaN(d.getTime())) return String(v);
    return new Intl.DateTimeFormat(this.locale(), {
      year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit',
    }).format(d);
  });
}
